/** Steps for a tool slug, falling back to English when German is missing. */
export function getHowToSteps(
  slug: string,
  locale?: string
): string[] {
  const de = locale && locale.startsWith("de") ? HOW_TO_DE[slug] : undefined;
  return de && de.length ? de : HOW_TO_EN[slug] || [];
}
